if test "$typed" != I\ ACCEPT
then
  echo
  echo You didn\'t accept the license. Extraction aborted.
  exit 2
fi

echo

tail -n +315 $0 | tar zxv

if test $? != 0
then
  echo
  echo ERROR: Couldn\'t extract files. 1>&2
  exit 3
